INSERT INTO `evenements` VALUES (1,'Rentrée Solennelle et Conférence Inaugurale 2025-2026','rentree-solennelle-2025','Événement','L\'Université ECOB a célébré l\'accueil de sa nouvelle promotion d\'étudiants bilingues en Gestion, Agro-Business et Mines.','<p>Une cérémonie prestigieuse s\'est tenue sur le campus de Sotuba ACI en présence du corps professoral, des partenaires industriels et des nouveaux étudiants. L\'accent a été mis sur le leadership bilingue et l\'insertion professionnelle immédiate.</p>','image','assets/images/img2.jpg',NULL,'2025-10-15','publie',0,'2026-10-03 21:24:10'),(2,'Lancement des Nouvelles Filières : Mines & Géologie, Agro-Business','lancement-nouvelles-filieres','Formation','Ouverture officielle des départements d\'ingénierie minière et d\'entrepreneuriat agroalimentaire pour répondre aux besoins économiques du Mali.','<p>ECOB élargit ses horizons en proposant des filières à fort impact stratégique : Mines & Géologie et Agro-Business. Équipements de pointe, stages de terrain et certifications internationales sont au programme.</p>','image','assets/images/img1.jpg',NULL,'2025-11-02','publie',0,'2026-10-03 21:24:10'),(3,'Immersion en Entreprise et Partenariats Internationaux','immersion-entreprises-partenariats','Activités','Signature de conventions de stages et d\'échanges pour nos promotions de DUT, Licence et Master.','<p>Les étudiants d\'ECOB bénéficient d\'un réseau étendu de partenaires au Mali et à l\'international, garantissant des stages pratiques dès la première année d\'études.</p>','image','assets/images/img3.jpg',NULL,'2025-12-10','publie',0,'2026-10-03 21:24:10'),(4,'Fete de lancement',NULL,'Actualité','Cet evenement marque le debut d\'une annees de succes de discipline de divertissement egalement alors rejoingner nous pour cette grande aventure','Cet evenement marque le debut d\'une annees de succes de discipline de divertissement egalement alors rejoingner nous pour cette grande aventure\r\nla reprise est prevu le 13 octobre alors venu vite vous inscrire car le debut marquera la fin','image','assets/uploads/event_20261007_212248_bc3a29.jpg','','2026-10-07','publie',0,'2026-10-07 21:22:48');
/*!40000 ALTER TABLE `evenements` ENABLE KEYS */;
UNLOCK TABLES;

