INSERT INTO `filieres` VALUES (1,'gestion','Gestion des Entreprises et Administrations (GEA)','DUT & Licence','2 à 3 ans','🏛️','Une formation complète en pilotage organisationnel, droit des affaires, stratégie d\'entreprise et contrôle de gestion.','Directeur administratif, Gestionnaire de PME, Auditeur interne','assets/uploads/filiere_1791067402.jpg',0,'actif','2026-10-03 22:31:12'),(2,'gestion','Gestion des Ressources Humaines (GRH)','DUT & Licence','2 à 3 ans','👥','Développez le capital humain : recrutement, gestion des carrières, climat social, paie et communication interne.','Responsable RH, Chargé de recrutement, Gestionnaire de paie','assets/images/img2.jpg',2,'actif','2026-10-03 22:31:12'),(3,'gestion','Finance, Banque & Comptabilité','DUT & Licence','2 à 3 ans','📊','Maîtrisez les états financiers, l\'analyse des risques de crédit, la fiscalité OHADA et la gestion de trésorerie bancaire.','Analyste financier, Comptable en cabinet, Conseiller bancaire','assets/images/img1.jpg',3,'actif','2026-10-03 22:31:12'),(4,'gestion','Marketing & Commerce International','DUT & Licence','2 à 3 ans','🚀','Concevez des stratégies de marque innovantes, développez les ventes et pilotez des transactions transfrontalières.','Chef de produit, Responsable commercial export, Brand manager','assets/images/img3.jpg',4,'actif','2026-10-03 22:31:12'),(5,'gestion','Logistique, Transport & Transit','DUT & Licence','2 à 3 ans','🚢','Optimisez la chaîne d\'approvisionnement (Supply Chain), la gestion des entrepôts et les procédures douanières.','Gestionnaire de stock, Coordinateur logistique, Déclarant en douane','assets/images/img2.jpg',5,'actif','2026-10-03 22:31:12'),(6,'agro','Management des Entreprises Agricoles','DUT & Licence','2 à 3 ans','🌾','Apprenez à piloter une exploitation moderne, gérer une coopérative agricole et négocier sur les marchés de gros régionaux.','Gérant d\'exploitation, Conseiller agricole, Responsable coopérative','assets/images/img1.jpg',1,'actif','2026-10-03 22:31:12'),(7,'agro','Transformation Agroalimentaire & Packaging','DUT & Licence','2 à 3 ans','🏭','Spécialisez-vous dans la conservation, le packaging, la transformation des céréales, fruits et bétail en produits finis.','Responsable d\'unité de production, Contrôleur qualité HACCP','assets/images/img3.jpg',2,'actif','2026-10-03 22:31:12'),(8,'agro','Génie Hydro-Agricole & Irrigation','DUT & Licence','2 à 3 ans','💧','Maîtrisez les systèmes d\'irrigation goutte-à-goutte, la gestion raisonnée de l\'eau et l\'aménagement des bassins.','Technicien hydraulique agricole, Superviseur de forages solaires','assets/images/img2.jpg',3,'actif','2026-10-03 22:31:12'),(9,'mine','Exploitation Minière & Carrières','DUT & Licence','2 à 3 ans','⛏️','Supervisez les opérations d\'extraction minière à ciel ouvert ou souterraine, la fragmentation et les normes HSE.','Superviseur de mine, Technicien de forage-minage, Inspecteur HSE','assets/images/img2.jpg',1,'actif','2026-10-03 22:31:12'),(10,'mine','Géologie Appliquée & Exploration','DUT & Licence','2 à 3 ans','🪨','Spécialisez-vous dans la prospection des gisements, l\'échantillonnage géophysique et la modélisation SIG du sous-sol.','Géologue de terrain, Cartographe SIG, Technicien de laboratoire minéral','assets/images/img1.jpg',2,'actif','2026-10-03 22:31:12'),(11,'mine','Hydrogéologie & Gestion de l\'Eau','DUT & Licence','2 à 3 ans','💧','Détectez et gérez les nappes phréatiques, planifiez les forages et prévenez la contamination des eaux en zone minière.','Hydrogéologue, Responsable environnemental de site minier','assets/images/img4.jpg',3,'actif','2026-10-03 22:31:12');
/*!40000 ALTER TABLE `filieres` ENABLE KEYS */;
