INSERT INTO `pages_contenu` VALUES ('a-propos','À Propos d\'ECOB University','Découvrez l\'histoire, la vocation et les valeurs cardinales qui animent notre communauté académique au quotidien.','Histoire & Valeurs','<p>Fondée à Bamako par un collège d\'universitaires et de professionnels chevronnés, ECOB est née du constat que les jeunes diplômés manquaient souvent de deux atouts décisifs : la maîtrise pratique du monde des affaires et le bilinguisme français-anglais.</p><p>En alliant des maquettes académiques actualisées aux stages obligatoires en immersion professionnelle, notre université a forgé une réputation d\'excellence auprès des recruteurs au Mali et dans l\'espace UEMOA.</p>',NULL,'assets/images/img3.jpg','2026-10-03 22:31:12'),('organisation','Organisation & Gouvernance','Une structure administrative moderne, réactive et orientée vers la réussite et l\'épanouissement de chaque étudiant.','Gouvernance','<p>L\'organisation d\'ECOB University s\'articule autour d\'une gouvernance participative impliquant la Présidence, la Direction Académique, le Conseil Pédagogique et les représentants des étudiants pour garantir une écoute permanente et une qualité d\'enseignement optimale.</p>',NULL,'assets/images/img1.jpg','2026-10-03 22:31:12'),('presentation','Présentation d\'ECOB University','Une institution d\'enseignement supérieur d\'excellence dédiée à l\'émergence des compétences managériales et techniques en Afrique.','Institution & Vision','<p>Fondée avec l\'ambition d\'apporter une réponse concrète aux défis d\'insertion professionnelle des diplômés, <strong>ECOB University (École de Business Bilingue)</strong> s\'est imposée comme une référence de l\'enseignement supérieur privé au Mali.</p><p>Notre modèle pédagogique combine l\'assimilation théorique rigoureuse, la pratique en entreprise dès le premier cycle et la maîtrise courante de l\'anglais des affaires, ouvrant à nos étudiants les portes des multinationales, des organisations non gouvernementales et des institutions sous-régionales.</p>',NULL,'assets/images/img2.jpg','2026-10-03 22:31:12'),('reglement','Règlement Intérieur & Charte d\'Éthique','Les règles de vie commune garantissant un climat d\'études propice à l\'excellence, au respect mutuel et à l\'épanouissement intellectuel.','Vie Universitaire','<div class=\"chapitre\">\n    <h4><i class=\"fas fa-landmark\"></i> Chapitre 1 : Dispositions Générales</h4>\n    <div class=\"article\">\n        <h5>Article 1 : Objet et Champ d\'Application</h5>\n        <p>Le présent règlement intérieur a pour objet de définir les règles de vie, d\'études et de fonctionnement au sein de l\'Université ECOB, École de Business Bilingue Mali. Il s\'applique obligatoirement à l\'ensemble des étudiants, auditeurs libres, enseignants et membres du personnel administratif et technique.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 2 : Valeurs et Principes</h5>\n        <p>L\'Université ECOB promeut l\'excellence académique, l\'intégrité intellectuelle, la discipline, le respect mutuel et le bilinguisme. Tout membre de la communauté universitaire est tenu d\'honorer ces valeurs fondamentales dans toutes ses activités d\'apprentissage et de vie de campus.</p>\n    </div>\n</div>\n\n<div class=\"chapitre\">\n    <h4><i class=\"fas fa-user-check\"></i> Chapitre 2 : Admission et Inscription</h4>\n    <div class=\"article\">\n        <h5>Article 3 : Conditions d\'Admission</h5>\n        <p>L\'admission aux différents cycles de formation (DUT, Licence, Master) à l\'Université ECOB est conditionnée par la conformité du dossier académique requis, l\'admissibilité au contrôle des prérequis et le règlement des frais de scolarité selon les échéances fixées par l\'administration.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 4 : Inscription Administrative et Pédagogique</h5>\n        <p>Les étudiants doivent impérativement valider leur inscription administrative et pédagogique au début de chaque semestre académique. Seule une inscription validée donne droit à la délivrance de la carte d\'étudiant et à l\'accès aux salles de cours, laboratoires et examens.</p>\n    </div>\n</div>\n\n<div class=\"chapitre\">\n    <h4><i class=\"fas fa-graduation-cap\"></i> Chapitre 3 : Vie Académique & Évaluations</h4>\n    <div class=\"article\">\n        <h5>Article 5 : Assiduité et Ponctualité</h5>\n        <p>La présence à l\'ensemble des enseignements théoriques, travaux dirigés (TD), travaux pratiques (TP), ateliers et conférences est obligatoire. Tout retard supérieur à 15 minutes entraîne le refus d\'accès en salle de cours. Toute absence doit être motivée et justifiée par un justificatif officiel sous 48 heures ouvrées.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 6 : Évaluations, Contrôles et Examens</h5>\n        <p>Le système d\'évaluation repose sur le contrôle continu et des examens semestriels. Toute fraude, plagiat ou tentative de tricherie lors des évaluations donne lieu à l\'exclusion immédiate de la salle et à la comparution devant le Conseil de Discipline, avec risque d\'exclusion définitive sans remboursement des frais.</p>\n    </div>\n</div>\n\n<div class=\"chapitre\">\n    <h4><i class=\"fas fa-shield-alt\"></i> Chapitre 4 : Comportement et Discipline</h4>\n    <div class=\"article\">\n        <h5>Article 7 : Tenue Vestimentaire & Respect Mutuel</h5>\n        <p>En tant que futurs cadres et dirigeants d\'entreprises, les étudiants doivent adopter une tenue décente, soignée et professionnelle en toute circonstance sur le campus. Tout comportement agressif, harcèlement, discrimination, usage de stupéfiants ou perturbation des cours est formellement prohibé.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 8 : Utilisation et Respect des Installations</h5>\n        <p>Les infrastructures, équipements informatiques, salles de conférences et matériels de laboratoire doivent être préservés avec le plus grand soin. Toute dégradation volontaire entraîne la réparation financière intégrale du préjudice causé, assortie de sanctions disciplinaires.</p>\n    </div>\n</div>\n\n<div class=\"chapitre\">\n    <h4><i class=\"fas fa-users\"></i> Chapitre 5 : Activités Extrascolaires & Campus</h4>\n    <div class=\"article\">\n        <h5>Article 9 : Clubs Universitaires et Associations</h5>\n        <p>L\'université encourage l\'initiative étudiante, l\'entrepreneuriat, les clubs d\'anglais, de débats et de sport. Toutes les initiatives doivent être déclarées et conformes à l\'éthique et aux règlements de l\'établissement.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 10 : Événements, Séminaires et Manifestations</h5>\n        <p>Toute manifestation ou réunion sur le campus doit recevoir l\'autorisation préalable écrite du Secrétariat Général ou de la Direction Académique, garantissant la sécurité des personnes et des biens.</p>\n    </div>\n</div>\n\n<div class=\"chapitre\">\n    <h4><i class=\"fas fa-gavel\"></i> Chapitre 6 : Dispositions Finales & Sanctions</h4>\n    <div class=\"article\">\n        <h5>Article 11 : Échelle des Sanctions Disciplinaires</h5>\n        <p>Toute infraction aux dispositions du présent règlement expose son auteur à l\'une des sanctions suivantes, selon la gravité de la faute : avertissement verbal, blâme avec inscription au dossier académique, suspension temporaire, ou exclusion définitive prononcée par le Conseil de Discipline.</p>\n    </div>\n    <div class=\"article\">\n        <h5>Article 12 : Entrée en Vigueur et Modification</h5>\n        <p>Le présent règlement intérieur entre en vigueur dès sa publication officielle. L\'administration se réserve le droit de l\'actualiser selon les impératifs pédagogiques et légaux, toute modification étant notifiée à l\'ensemble des étudiants.</p>\n    </div>\n</div>\n\n<div class=\"annexes\">\n    <h4><i class=\"fas fa-scroll\"></i> Annexes Officielles</h4>\n    <div class=\"annexe\">\n        <h5>Annexe 1 : Charte d\'Éthique de l\'Étudiant ECOB</h5>\n        <p>Rappel solennel des devoirs de probité, d\'esprit de service, de fraternité et d\'engagement citoyen partagés par tous les ambassadeurs d\'ECOB University.</p>\n    </div>\n    <div class=\"annexe\">\n        <h5>Annexe 2 : Procédure de Réclamation et de Médiation</h5>\n        <p>Dispositif d\'écoute et de médiation confidentielle permettant à tout étudiant de soumettre une réclamation ou un litige académique auprès du Médiateur Universitaire en toute équité.</p>\n    </div>\n</div>',NULL,'assets/images/img4.jpg','2026-10-07 19:27:58');
/*!40000 ALTER TABLE `pages_contenu` ENABLE KEYS */;
UNLOCK TABLES;

